import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	// ------------------------------------------------------------
	// Geometry & Material
	// ------------------------------------------------------------
	const geometry = new PlaneGeometry(1, 1);
	const tex = ctx.textureLoader(config.assets?.imageUrl);
	const texNode = texture(tex);
	const material = new MeshBasicNodeMaterial();
	material.map = texNode;

	// ------------------------------------------------------------
	// Mesh setup
	// ------------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	const pos = config.position || { x: 0, y: 0, z: 0 };
	const rot = config.rotation || { x: 0, y: 0, z: 0 };
	const scl = config.scale || { x: 1, y: 1, z: 1 };

	mesh.position.set(pos.x, pos.y, pos.z);
	mesh.rotation.set(rot.x, rot.y, rot.z);
	mesh.scale.set(scl.x, scl.y, scl.z);

	// ------------------------------------------------------------
	// Cinematic primitives (if any)
	// ------------------------------------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const primitive of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[primitive.name];
			if (typeof fn === 'function') {
				fn(mesh, primitive.params);
			}
		}
	}

	// ------------------------------------------------------------
	// Interaction state
	// ------------------------------------------------------------
	const originalY = mesh.position.y;
	const hoverTweenKey = Symbol('hoverTween');
	const clickTimelineKey = Symbol('clickTimeline');

	// ------------------------------------------------------------
	// Event handlers
	// ------------------------------------------------------------
	mesh.userData.handlers = {};

	// Hover – rise‑in effect (subtle lift of 0.15 units)
	mesh.userData.handlers.hover = (enter) => {
		if (mesh[hoverTweenKey]) {
			mesh[hoverTweenKey].kill();
			delete mesh[hoverTweenKey];
		}
		if (enter) {
			mesh[hoverTweenKey] = gsap.to(mesh.position, {
				y: originalY + 0.15,
				duration: 0.2,
				ease: 'power3.out',
			});
		} else {
			mesh[hoverTweenKey] = gsap.to(mesh.position, {
				y: originalY,
				duration: 0.2,
				ease: 'power3.out',
			});
		}
	};

	// Click – press‑down animation + event emission
	mesh.userData.handlers.click = () => {
		if (mesh[clickTimelineKey]) {
			mesh[clickTimelineKey].kill();
			delete mesh[clickTimelineKey];
		}
		const tl = gsap.timeline();
		tl.to(
			mesh.scale,
			{
				x: 0.97,
				y: 0.97,
				z: 0.97,
				duration: 0.12,
				ease: 'back.out(1.7)',
			},
			0,
		).to(
			mesh.scale,
			{
				x: 1,
				y: 1,
				z: 1,
				duration: 0.12,
				ease: 'back.out(1.7)',
			},
			'>',
		);
		mesh[clickTimelineKey] = tl;

		if (typeof ctx.emit === 'function') {
			ctx.emit('hub-pricing.select');
		}
	};

	// ------------------------------------------------------------
	// Cleanup
	// ------------------------------------------------------------
	mesh.userData.cleanup = () => {
		gsap.killTweensOf(mesh.position);
		gsap.killTweensOf(mesh.scale);
		if (mesh[hoverTweenKey]) mesh[hoverTweenKey].kill();
		if (mesh[clickTimelineKey]) mesh[clickTimelineKey].kill();

		geometry.dispose();
		material.dispose();
		// Do not dispose the texture if it is shared globally.
		if (tex && typeof tex.dispose === 'function' && tex.userData?.owned) {
			tex.dispose();
		}
	};

	return mesh;
}
